package com.aistock.market.adminquery;

import static com.aistock.market.adminquery.AdminMarketRecords.*;
import com.aistock.common.adminmarket.AdminMarketQuery.DetailFilter;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CoverageDiagnosticsTest {
 private final LocalDate start=LocalDate.parse("2026-10-19");
 private final CoverageDiagnostics calc=new CoverageDiagnostics();
 private DetailFilter window(int days){return new DetailFilter(start,start.plusDays(days-1));}
 private VersionBounds bounds(int days){return new VersionBounds(start,start.plusDays(days-1));}
 private DiagnosticBar bar(int day,int status){return new DiagnosticBar(start.plusDays(day),new BigDecimal("10"),new BigDecimal("12"),new BigDecimal("9"),new BigDecimal("11"),new BigDecimal("100"),new BigDecimal("1100"),status);}
 private List<CalendarDay> calendar(int days){var d=new ArrayList<CalendarDay>();for(int i=0;i<days;i++)d.add(new CalendarDay(start.plusDays(i),true));return d;}
 @Test void distinguishesRecordedSuspensionFromMissingOpenDay(){var bars=List.of(bar(0,1),bar(1,0),bar(2,1),bar(3,1));var d=calc.calculate(window(5),bounds(5),bars,calendar(5));assertEquals("NEEDS_REVIEW",d.state());assertEquals("5",d.knownOpenDays());assertEquals("4",d.barDays());assertEquals("3",d.tradedRowDays());assertEquals("1",d.suspendedRowDays());assertEquals("1",d.suspectedMissingOpenDays().count());assertEquals(List.of(start.plusDays(4)),d.suspectedMissingOpenDays().sampleDates());assertEquals(4,bars.size());}
 @Test void closedDaysAndUnknownCalendarAreNotInventedOpenDays(){var cal=calendar(5);cal.set(4,new CalendarDay(start.plusDays(4),false));var bars=List.of(bar(0,1),bar(1,1),bar(2,1),bar(3,1));assertEquals("NO_RECORDED_ISSUES",calc.calculate(window(5),bounds(5),bars,cal).state());var withClosed=new ArrayList<>(bars);withClosed.add(bar(4,1));var d=calc.calculate(window(5),bounds(5),withClosed,cal);assertEquals("ISSUES",d.state());assertEquals("1",d.barsOnClosedDays().count());cal.remove(4);d=calc.calculate(window(5),bounds(5),bars,cal);assertEquals("INCOMPLETE_EVIDENCE",d.state());assertEquals("1",d.unknownCalendarDays());assertEquals("0",d.suspectedMissingOpenDays().count());}
 @Test void clipsToVersionAndSeparatesOutsideCoverage(){var d=calc.calculate(window(5),new VersionBounds(start.plusDays(1),start.plusDays(2)),List.of(bar(1,1),bar(2,1)),calendar(5));assertEquals("3",d.outsideCoverageDays());assertEquals("2",d.knownOpenDays());assertEquals(start.plusDays(1),d.effectiveFrom());assertEquals("NO_RECORDED_ISSUES",d.state());d=calc.calculate(window(5),new VersionBounds(start.minusDays(10),start.minusDays(1)),List.of(),List.of());assertEquals("OUTSIDE_COVERAGE",d.state());assertNull(d.effectiveFrom());assertNull(d.effectiveTo());assertEquals("5",d.outsideCoverageDays());assertEquals("0",d.suspectedMissingOpenDays().count());}
 @Test void detectsInvalidRowsOncePerDateAndKeepsUnknownsVisible(){var bad=new DiagnosticBar(start,new BigDecimal("-1"),BigDecimal.ZERO,BigDecimal.TEN,new BigDecimal("20"),BigDecimal.ZERO,null,2);var d=calc.calculate(window(1),bounds(1),List.of(bad),List.of());assertEquals("ISSUES",d.state());assertEquals("1",d.invalidRowDays().count());assertEquals("1",d.unknownCalendarDays());var trade=new DiagnosticBar(start,BigDecimal.TEN,new BigDecimal("12"),new BigDecimal("9"),new BigDecimal("11"),BigDecimal.ZERO,null,1);assertEquals("1",calc.calculate(window(1),bounds(1),List.of(trade),calendar(1)).invalidRowDays().count());}
 @Test void dateSamplesAreBoundedAndSorted(){var d=calc.calculate(window(25),bounds(25),List.of(),calendar(25));assertEquals("25",d.suspectedMissingOpenDays().count());assertEquals(20,d.suspectedMissingOpenDays().sampleDates().size());assertEquals(start,d.suspectedMissingOpenDays().sampleDates().get(0));assertTrue(d.suspectedMissingOpenDays().truncated());}
 @Test void rejectsUninterpretableBoundsAndDuplicateEvidence(){assertThrows(IllegalArgumentException.class,()->calc.calculate(window(367),bounds(367),List.of(),List.of()));assertThrows(IllegalArgumentException.class,()->calc.calculate(window(1),new VersionBounds(null,start),List.of(),List.of()));assertThrows(IllegalArgumentException.class,()->calc.calculate(window(1),bounds(1),List.of(bar(0,1),bar(0,1)),calendar(1)));assertThrows(IllegalArgumentException.class,()->calc.calculate(window(1),bounds(1),List.of(),List.of(new CalendarDay(start,true),new CalendarDay(start,false))));}
}
